from h import *
R=[]
R.append((6811573,{
"es":L("Tazón de yogur griego con cerezas y linaza","Este tazón de yogur con cerezas y linaza es una mezcla sencilla y nutritiva de yogur griego cremoso, cerezas sin azúcar masticables y linaza con sabor a nuez. Se prepara en minutos y ofrece una combinación satisfactoria de texturas y dulzor natural, ideal para un desayuno o merienda rápidos.","1","1 taza",
["3/4 taza de yogur griego","1 cucharada de semillas de linaza enteras","1/4 taza de cerezas secas sin azúcar"],
["Con una cuchara, ponga 3/4 taza de yogur griego sin grasa en un tazón.","Espolvoree uniformemente 1 cucharada de linaza por encima.","Agregue 1/4 taza de cerezas secas sin azúcar.","Mezcle suavemente para combinar, o déjelo en capas si prefiere más textura.","Disfrútelo de inmediato."]),
"ar":L("وعاء زبادي يوناني بالكرز وبذور الكتان","وعاء الزبادي بالكرز وبذور الكتان هذا مزيج بسيط ومغذٍّ من الزبادي اليوناني الكريمي والكرز المجفف غير المحلّى ذي القوام الطري وبذور الكتان ذات النكهة الشبيهة بالمكسرات. يُحضَّر في دقائق ويمنحك مزيجًا مُرضيًا من القوام والحلاوة الطبيعية، وهو مثالي لفطور أو وجبة خفيفة سريعة.","1","1 كوب",
["¾ كوب زبادي يوناني","1 ملعقة كبيرة بذور كتان كاملة","¼ كوب كرز مجفف غير محلّى"],
["ضع ¾ كوب من الزبادي اليوناني الخالي من الدسم في وعاء.","انثر 1 ملعقة كبيرة من بذور الكتان بالتساوي فوق الزبادي.","أضف ¼ كوب من الكرز المجفف غير المحلّى.","حرّك برفق للمزج، أو اتركه على شكل طبقات إذا كنت تفضّل قوامًا أكثر.","استمتع به فورًا."])}))
R.append((6813293,{
"es":L("Chícharos chinos salteados con semillas de ajonjolí","Disfrute la perfección crujiente de los chícharos chinos salteados con semillas de ajonjolí, una opción nutritiva y baja en calorías que combina el delicado dulzor de los chícharos chinos con el rico sabor a nuez del ajonjolí, para un acompañamiento apto para personas con diabetes.","4","1/2 taza",
["2 tazas de chícharos chinos","1 cucharada de mayonesa light","1 cucharada de semillas de ajonjolí (tostadas)","1 cucharada de salsa de soya baja en sodio"],
["Lleve a ebullición una olla mediana con agua y coloque encima una canasta para cocinar al vapor.","Agregue los chícharos chinos y cocínelos al vapor hasta que tomen un color verde brillante y estén tiernos.","Escúrralos y mézclelos con la mayonesa, las semillas de ajonjolí tostadas, la salsa de soya, la sal y la pimienta."]),
"ar":L("بازلاء الثلج المحمّصة بالسمسم","استمتع بالقوام المقرمش المثالي لبازلاء الثلج المحمّصة بالسمسم، وهي خيار مغذٍّ وقليل السعرات الحرارية يجمع بين الحلاوة الرقيقة لبازلاء الثلج والنكهة الغنية للسمسم الشبيهة بالمكسرات، ليكون طبق جانبي مناسبًا لمرضى السكري.","4","½ كوب",
["2 كوب بازلاء الثلج","1 ملعقة كبيرة مايونيز خفيف","1 ملعقة كبيرة بذور سمسم (محمّصة)","1 ملعقة كبيرة صلصة صويا منخفضة الصوديوم"],
["اغلِ الماء في قدر متوسط وضع فوقه سلة للطهي بالبخار.","أضف بازلاء الثلج واطهُها على البخار حتى يصبح لونها أخضر زاهيًا وتنضج.","صفِّها وقلّبها مع المايونيز وبذور السمسم المحمّصة وصلصة الصويا والملح والفلفل."])}))
R.append((6814777,{
"es":L("Salmón con puré de chícharos","El salmón rosado se sirve sobre una hermosa base verde de puré de chícharos en este elegante platillo. Si lo prepara para una fiesta, puede cocinar el pescado y el puré con un día de anticipación y recalentarlos antes de servir.","4","1 pieza de salmón + 1/2 taza de puré",
["1/4 cucharadita de comino molido","1/4 cucharadita de cúrcuma","1/4 cucharadita de pimienta de Jamaica molida","1/4 cucharadita de cilantro molido","1 libra de chícharos dulces frescos","2 cucharadas de jugo de limón","1/2 taza de caldo de verduras bajo en sodio","1/4 cucharadita de sal","1/8 cucharadita de pimienta negra","1 cucharadita de aceite de oliva","1 libra de filete de salmón (cortado en 4 piezas iguales)","1 limón mediano (en cuartos)"],
["Precaliente el horno a 425° F. En un tazón pequeño, mezcle el comino, la cúrcuma, la pimienta de Jamaica y el cilantro, y reserve.","En una licuadora, combine los chícharos, el jugo de 1 limón, el caldo de verduras, la sal y la pimienta. Licúe hasta obtener un puré suave.","Engrase una fuente para hornear con el aceite de oliva. Coloque el salmón en la fuente y voltéelo para cubrirlo con el aceite. Espolvoree cada pieza con la mezcla de especias y el jugo restante de 1 limón. Hornee de 15 a 20 minutos, o hasta que el salmón esté bien cocido.","Vierta el puré en una fuente para servir. Coloque el salmón encima. Decore con gajos de limón."]),
"ar":L("سمك السلمون مع هريس البازلاء","يُقدَّم السلمون الوردي على طبقة خضراء جميلة من هريس البازلاء في هذا الطبق الأنيق. إذا كنت تحضّر الطبق لحفلة، يمكنك طهي السمك وهريس البازلاء قبل يوم واحد وإعادة تسخينهما قبل التقديم.","4","1 قطعة سلمون + ½ كوب هريس",
["¼ ملعقة صغيرة كمون مطحون","¼ ملعقة صغيرة كركم","¼ ملعقة صغيرة بهار حلو (أول سبايس) مطحون","¼ ملعقة صغيرة كزبرة مطحونة","1 رطل بازلاء حلوة طازجة","2 ملعقة كبيرة عصير ليمون","½ كوب مرق خضار قليل الصوديوم","¼ ملعقة صغيرة ملح","⅛ ملعقة صغيرة فلفل أسود","1 ملعقة صغيرة زيت زيتون","1 رطل شرائح سلمون (مقطّعة إلى 4 قطع متساوية)","1 ليمونة متوسطة (مقطّعة أرباعًا)"],
["سخّن الفرن مسبقًا إلى 425° فهرنهايت (220° مئوية). في وعاء صغير اخلط الكمون والكركم والبهار الحلو والكزبرة وضعه جانبًا.","في الخلاط، اجمع البازلاء وعصير 1 ليمونة ومرق الخضار والملح والفلفل. اخلط حتى يصبح الهريس ناعمًا.","ادهن طبق الخبز بزيت الزيتون. ضع السلمون في الطبق وقلّبه ليتغطى بالزيت. رشّ كل قطعة بخليط التوابل وبعصير 1 ليمونة المتبقي. اخبز لمدة 15 إلى 20 دقيقة، أو حتى ينضج السلمون تمامًا.","اسكب الهريس في طبق التقديم. ضع السلمون فوقه. زيّن بشرائح الليمون."])}))
R.append((6815565,{
"es":L("Sopa de zanahoria con jengibre y especias","Esta sabrosa sopa de zanahoria con jengibre y especias es un viaje culinario que cruza fronteras, inspirado en cocinas de todo el mundo. Con un toque de especias y un matiz de jengibre reconfortante, ofrece el equilibrio perfecto entre lo salado y lo dulce. Esta receta apta para personas con diabetes combina muy bien con una ensalada cremosa, como la Ensalada de coles de Bruselas con aguacate, alcachofas y aderezo cremoso de miel y mostaza.","8","1 taza",
["1 libra de zanahorias (peladas y picadas)","1 cebolla entera (picada)","2 dientes de ajo (picados)","2 cucharadas de aceite de oliva","2 cucharadas de jengibre fresco (rallado)","1 cucharadita de cilantro molido","1/4 cucharadita de cúrcuma molida","1/4 cucharadita de sal","4 tazas de caldo de verduras bajo en sodio","1 taza de leche de coco light (sin azúcar)","1 manojo de cilantro fresco (para decorar)"],
["En una olla grande, caliente el aceite de oliva a fuego medio. Agregue la cebolla picada y saltéela hasta que esté transparente, de 4–5 minutos.","Agregue el ajo picado y el jengibre recién rallado. Saltee durante 1–2 minutos aproximadamente, hasta que suelten su aroma. Incorpore el cilantro molido y la cúrcuma. Cocine un minuto más para tostar las especias.","Agregue las zanahorias picadas a la olla y saltéelas unos minutos, cubriéndolas con las especias aromáticas.","Vierta el caldo de verduras y deje que la mezcla hierva a fuego lento. Tape la olla y cocine las zanahorias hasta que estén tiernas.","Cuando las zanahorias estén cocidas, use una licuadora de inmersión para hacer puré la sopa hasta que quede suave. También puede pasar la sopa con cuidado a una licuadora, licuarla hasta que quede suave y devolverla a la olla.","Incorpore la leche de coco y sazone la sopa con sal y pimienta al gusto.","Deje que la sopa hierva a fuego lento unos minutos más hasta que esté caliente.","Sirva la sopa de zanahoria con jengibre y especias caliente, decorada con cilantro fresco picado."]),
"ar":L("شوربة الجزر بالزنجبيل والتوابل","شوربة الجزر بالزنجبيل والتوابل اللذيذة هذه رحلة طهي تتجاوز الحدود، مستوحاة من مطابخ العالم. بلمسة من التوابل ونفحة من الزنجبيل الدافئ، تقدّم توازنًا مثاليًا بين المالح والحلو. تتناسب هذه الوصفة المناسبة لمرضى السكري جيدًا مع سلطة كريمية، مثل سلطة كرنب بروكسل مع الأفوكادو والخرشوف وصلصة العسل والخردل الكريمية.","8","1 كوب",
["1 رطل جزر (مقشّر ومقطّع)","1 حبة بصل كاملة (مفرومة)","2 فص ثوم (مفروم)","2 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة زنجبيل طازج (مبشور)","1 ملعقة صغيرة كزبرة مطحونة","¼ ملعقة صغيرة كركم مطحون","¼ ملعقة صغيرة ملح","4 كوب مرق خضار قليل الصوديوم","1 كوب حليب جوز الهند خفيف (غير محلّى)","1 حزمة كزبرة خضراء طازجة (للتزيين)"],
["في قدر كبير، سخّن زيت الزيتون على نار متوسطة. أضف البصل المفروم وقلّبه حتى يصبح شفافًا، 4–5 دقائق.","أضف الثوم المفروم والزنجبيل الطازج المبشور. قلّب لمدة 1–2 دقيقة تقريبًا حتى تفوح الرائحة. أضف الكزبرة المطحونة والكركم وحرّك. اطهُ لدقيقة أخرى لتحميص التوابل.","أضف الجزر المقطّع إلى القدر وقلّبه لبضع دقائق ليتغطى بالتوابل العطرية.","اسكب مرق الخضار واترك الخليط يغلي على نار هادئة. غطِّ القدر واترك الجزر يطهى حتى ينضج.","عندما ينضج الجزر، استخدم الخلاط اليدوي لهرس الشوربة حتى تصبح ناعمة. أو انقل الشوربة بحذر إلى الخلاط واخلطها حتى تصبح ناعمة، ثم أعدها إلى القدر.","أضف حليب جوز الهند وتبّل الشوربة بالملح والفلفل حسب الرغبة.","اترك الشوربة على نار هادئة بضع دقائق أخرى حتى تسخن جيدًا.","قدّم شوربة الجزر بالزنجبيل والتوابل ساخنة، مزيّنة بالكزبرة الخضراء الطازجة المفرومة."])}))
R.append((6815712,{
"ar":L("سلطة البطاطس بالأعشاب","الخردل والتوابل تجعل هذه النسخة الأكثر صحة من سلطة البطاطس التقليدية غنية بالنكهة. وهي طبق كلاسيكي للتجمعات، وستنال بالتأكيد إعجاب الجميع عند إحضارها إلى نزهة أو حفلة شواء في موقف السيارات أو أي مناسبة أخرى.","6","1 كوب",
["1 رطل بطاطس صغيرة جديدة (رقيقة القشرة، غير مقشّرة (حوالي 4 كوب مكعبات))","1 كوب كرفس (مقطّع شرائح)","½ حبة بصل أخضر (مقطّعة شرائح)","3 ملعقة كبيرة زبادي سادة (خالٍ من الدسم)","1 ملعقة كبيرة مايونيز خفيف","1½ ملعقة صغيرة خردل ديجون","½ ملعقة صغيرة ثوم (مفروم)","½ ملعقة صغيرة ريحان (مجفف)","¼ ملعقة صغيرة زعتر مجفف","¼ ملعقة صغيرة بصل مجفف مطحون","¼ ملعقة صغيرة ملح (اختياري)"],
["قطّع البطاطس إلى مكعبات بحجم 1 بوصة. ضعها في قدر متوسط وغطِّها بالماء. اتركها حتى تغلي. غطِّ القدر، وخفّف الحرارة، واتركها على نار هادئة 12 دقيقة أو حتى تنضج البطاطس. صفِّها.","اخلط مكونات الصلصة.","اخلط البطاطس الساخنة مع الكرفس والبصل الأخضر والصلصة. قدّمها ساخنة، أو ضعها في الثلاجة وقدّمها باردة."])}))
R.append((6817221,{
"es":L("Semillas de chía","Información nutricional de las semillas de chía","1","2 cucharadas",["2 cucharadas de semillas de chía"],[]),
"ar":L("بذور الشيا","المعلومات الغذائية لبذور الشيا","1","2 ملعقة كبيرة",["2 ملعقة كبيرة بذور شيا"],[])}))
R.append((6817273,{
"es":L("Arándanos azules, 1 taza","Información nutricional de 1 taza de arándanos azules","1","1 taza",["1 taza de arándanos azules"],[]),
"ar":L("توت أزرق، 1 كوب","المعلومات الغذائية لكوب واحد من التوت الأزرق","1","1 كوب",["1 كوب توت أزرق"],[])}))
R.append((6820054,{
"es":L("Magdalenas de \"pastel\" de zanahoria","Si le encanta el pastel de zanahoria, ¡le encantarán estas magdalenas de \"pastel\" de zanahoria! Bajas en carbohidratos y aptas para personas con diabetes, seguramente las disfrutará toda la familia.","12","1 magdalena",
["2 tazas de harina de almendra","1/2 taza de harina multiusos","1/2 taza de zanahorias (ralladas)","3 cucharadas de nueces (picadas)","1 cucharadita de polvo de hornear","1/2 cucharadita de bicarbonato de sodio","1 cucharadita de canela molida","1/2 cucharadita de nuez moscada molida","1/4 cucharadita de sal","3 huevos grandes","1/2 taza de puré de manzana (sin azúcar)","2 1/2 cucharadas de aceite de oliva","1/4 taza de leche de almendra sin azúcar","1/4 taza de sustituto de azúcar para hornear","1 cucharadita de extracto de vainilla"],
["Precaliente el horno a 350 grados F. Forre un molde para magdalenas con capacillos de papel.","En un tazón grande, mezcle la harina de almendra, la harina multiusos, las zanahorias ralladas, las nueces picadas, el polvo de hornear, el bicarbonato de sodio, la canela, la nuez moscada y la sal.","En otro tazón, bata los huevos, el puré de manzana, el aceite de oliva, la leche de almendra, el sustituto de azúcar y el extracto de vainilla.","Vierta los ingredientes húmedos sobre los ingredientes secos y mezcle hasta que apenas se integren.","Con una cuchara, distribuya la masa de manera uniforme en los moldecitos, llenando cada uno aproximadamente 2/3 de su capacidad.","Hornee en el horno precalentado de 18–20 minutos, o hasta que un palillo insertado en el centro salga limpio."]),
"ar":L("مافن \"كيك\" الجزر","إذا كنت تحب كيك الجزر، فستحب مافن \"كيك\" الجزر هذا! قليل الكربوهيدرات ومناسب لمرضى السكري، وسيستمتع به أفراد الأسرة جميعًا بلا شك.","12","1 كعكة مافن",
["2 كوب دقيق اللوز","½ كوب دقيق متعدد الاستخدامات","½ كوب جزر (مبشور)","3 ملعقة كبيرة جوز (مفروم)","1 ملعقة صغيرة بيكنج باودر","½ ملعقة صغيرة بيكربونات الصوديوم","1 ملعقة صغيرة قرفة مطحونة","½ ملعقة صغيرة جوزة الطيب المطحونة","¼ ملعقة صغيرة ملح","3 بيضات كبيرة","½ كوب صلصة التفاح (غير محلّاة)","2½ ملعقة كبيرة زيت زيتون","¼ كوب حليب اللوز غير المحلّى","¼ كوب بديل سكر للخبز","1 ملعقة صغيرة خلاصة الفانيلا"],
["سخّن الفرن مسبقًا إلى 350 درجة فهرنهايت (175° مئوية). بطّن صينية المافن بقوالب ورقية.","في وعاء كبير، اخلط دقيق اللوز والدقيق متعدد الاستخدامات والجزر المبشور والجوز المفروم والبيكنج باودر وبيكربونات الصوديوم والقرفة وجوزة الطيب والملح.","في وعاء آخر، اخفق البيض وصلصة التفاح وزيت الزيتون وحليب اللوز وبديل السكر وخلاصة الفانيلا.","اسكب المكونات السائلة على المكونات الجافة وحرّك حتى تمتزج فقط.","وزّع الخليط بالملعقة بالتساوي على قوالب المافن، واملأ كل قالب بنحو ⅔ سعته.","اخبز في الفرن المسخّن مسبقًا لمدة 18–20 دقيقة، أو حتى تخرج عود الأسنان نظيفة عند غرزها في الوسط."])}))
R.append((6820987,{
"ar":L("فطائر الخوخ المقرمشة الصغيرة","نعلم أن السمك مصدر جيد لأحماض أوميغا 3 الدهنية، وهي دهون صحية للقلب. لكن هذه الوصفة غنية جدًا بأحماض أوميغا 3 الدهنية من الجوز وبذور الكتان المطحونة، وهذه الأطعمة طرق لإدخال المزيد من أحماض أوميغا 3 الدهنية في نظامك الغذائي.","6","1 فطيرة خوخ مقرمشة (قالب رامكين)",
["3 كوب خوخ مجمّد (غير محلّى (أو 4-5 حبات خوخ طازج)، مقطّع شرائح)","¼ كوب ماء","1 ملعقة كبيرة محلٍّ قليل السعرات أو خالٍ منها","1 ملعقة صغيرة نشا الذرة","2 ملعقة كبيرة سمن نباتي قابل للدهن بنكهة الزبدة","2 ملعقة كبيرة بديل سكر بني قليل السعرات","⅓ كوب شوفان مجروش تقليدي (خالٍ من الغلوتين)","¼ كوب جوز (مفروم)","2 ملعقة كبيرة بذور كتان مطحونة","½ ملعقة صغيرة قرفة مطحونة"],
["سخّن الفرن مسبقًا إلى 350 درجة فهرنهايت (175° مئوية). رشّ ستة قوالب رامكين سعة 4 أونصات برذاذ الطهي.","في قدر متوسط، سخّن الخوخ والماء والمحلّي القليل السعرات أو الخالي منها على نار متوسطة إلى عالية. اتركه حتى يغلي، ثم خفّف الحرارة واتركه على نار هادئة 10 دقائق.","في وعاء صغير، اخلط 1 ملعقة صغيرة من نشا الذرة مع 1 ملعقة صغيرة من الماء البارد؛ حرّك حتى يصبح الخليط ناعمًا. اسكبه في القدر مع الخوخ وحرّك لمدة 1 دقيقة.","في وعاء صغير، اخلط مكونات طبقة التغطية المقرمشة بيديك.","وزّع خليط الخوخ بالتساوي على قوالب الرامكين الستة. قسّم طبقة التغطية المقرمشة بالتساوي وضعها فوق كل قالب خوخ.","ضع القوالب على صينية خبز واخبزها في الفرن لمدة 25–30 دقيقة."])}))
R.append((6821943,{
"es":L("Zanahorias arcoíris asadas","Las zanahorias arcoíris son moradas, amarillas, blancas y anaranjadas, y se pueden encontrar en muchos supermercados. Si no las encuentra, puede sustituirlas por zanahorias anaranjadas comunes. ¡Al asarlas, se convierten en un excelente bocadillo para comer con las manos para los niños!","6","1/2 taza",
["1 rocío, 0.25 gramo de aceite en aerosol antiadherente","2 libras de zanahorias arcoíris","3 cucharadas de aceite de oliva","1/4 cucharadita de pimienta negra molida"],
["Precaliente el horno a 425° F. Rocíe una bandeja para hornear con aceite en aerosol.","Pele las zanahorias y córtelas en rodajas y cuñas del mismo tamaño, de aproximadamente 1/2 pulgada cada una.","Coloque las zanahorias en la bandeja para hornear. Rocíe el aceite de oliva sobre las zanahorias y mezcle bien. Espolvoree con la pimienta.","Hornee durante 30 minutos, hasta que estén suaves y arrugadas. Pase a un tazón o a una fuente y sirva."]),
"ar":L("جزر قوس قزح المشوي","جزر قوس قزح أرجواني وأصفر وأبيض وبرتقالي، ويمكن العثور عليه في كثير من محلات البقالة. وإذا لم تجده، يمكنك استبداله بالجزر البرتقالي العادي. شيّ هذا الجزر يجعله طعامًا رائعًا يؤكل باليد للأطفال!","6","½ كوب",
["1 رشة، 0.25 غرام رذاذ طهي غير لاصق","2 رطل جزر قوس قزح","3 ملعقة كبيرة زيت زيتون","¼ ملعقة صغيرة فلفل أسود مطحون"],
["سخّن الفرن مسبقًا إلى 425° فهرنهايت (220° مئوية). رشّ صينية الخبز برذاذ الطهي.","قشّر الجزر وقطّعه إلى دوائر وأسافين متساوية الحجم، طول كل منها نحو ½ بوصة.","ضع الجزر على صينية الخبز. رشّ زيت الزيتون فوق الجزر وقلّبه جيدًا. رشّ الفلفل فوقه.","اخبزه لمدة 30 دقيقة، حتى يصبح طريًا ومجعّدًا. انقله إلى وعاء أو طبق وقدّمه."])}))
R.append((6822428,{
"es":L("Trucha a la parrilla con hierbas frescas y rodajas de limón","Esta estupenda receta fue sugerida por la amiga de Aviva Goldfarb y escritora gastronómica April Fulton. Aviva dice: \"Me encanta preparar trucha a la parrilla o en el horno; siempre sabe maravillosa, nunca demasiado a pescado, y se adapta a una variedad de sabores y técnicas de preparación. Lo que la hace aún mejor es que la trucha figura en la lista de opciones 'ecológicamente mejores' del proyecto Oceans Alive del Environmental Defense Fund. Sírvala con arroz integral y brócoli a la parrilla para una comida completa\".","4","1 trucha",
["2 cucharadas de menta fresca (finamente picada)","2 cucharadas de romero fresco (finamente picado)","2 limones medianos (dividido)","4 truchas enteras (de aproximadamente 7 onzas cada una, limpias, evisceradas y sin cabeza (el pescadero puede hacerlo por usted))","1 cucharada de aceite de oliva extra virgen","1/2 cucharadita de sal kosher","1/4 cucharadita de pimienta negra"],
["PREPARE CON ANTICIPACIÓN O DELEGUE: Ralle la cáscara y exprima el jugo de los limones.","Precaliente la parrilla a fuego medio y unte aceite en las rejillas para evitar que el pescado se pegue. (También puede hornear la trucha a 400° F durante unos 25 minutos). En un tazón pequeño, mezcle las hierbas picadas, la ralladura de 1 1/2 limones y el jugo de 1 limón. Corte el otro limón en rodajas finas.","Coloque las truchas sobre una tabla de cortar, con la piel hacia arriba, y unte la piel con aceite de oliva para cubrirla. Voltee el pescado y frote la mezcla de limón y hierbas sobre la carne de la trucha, sazone con la sal y la pimienta, y coloque las rodajas de limón sobre una mitad de cada trucha. Cierre las truchas sobre las hierbas y las rodajas de limón, y pase el pescado a la parrilla.","Ase el pescado con la tapa cerrada, sin voltearlo, durante 8 minutos o hasta que la carne esté opaca y se desmenuce. Con una espátula, pase con cuidado las truchas a un plato para servir. Decore el plato con unas hojas de menta fresca y ramitas de romero, si lo desea.","INSTRUCCIONES PARA OLLA DE COCCIÓN LENTA: Coloque cada pieza de pescado sobre un trozo individual de papel aluminio, rellene cada una con las especias y el limón. Cierre las truchas sobre las hierbas y las rodajas de limón, y doble el papel aluminio formando un paquete que rodee por completo el pescado. Coloque los paquetes en la olla de cocción lenta y cocine a temperatura baja de 8–10 horas o a temperatura alta de 4–5 horas. (Los tiempos de cocción en la olla de cocción lenta pueden variar; conozca bien su olla y, si es necesario, ajuste los tiempos de cocción según corresponda).","POTENCIADOR DE SABOR: Sazone el pescado en la mesa con pimienta negra recién molida o con sazonador de limón y pimienta."]),
"ar":L("سمك السلمون المرقط المشوي بالأعشاب الطازجة وشرائح الليمون","اقترحت هذه الوصفة الرائعة صديقةُ أفيفا غولدفارب، الكاتبة في شؤون الطعام أبريل فولتون. تقول أفيفا: \"أحب تحضير سمك السلمون المرقط على الشواية أو في الفرن؛ فطعمه رائع دائمًا ولا تكون رائحة السمك فيه قوية، ويتكيف مع مجموعة متنوعة من النكهات وتقنيات التحضير. وما يجعله أفضل أنه مدرج في قائمة الخيارات 'الأفضل بيئيًا' ضمن مشروع Oceans Alive التابع لصندوق الدفاع عن البيئة (Environmental Defense Fund). قدّمه مع الأرز البني والبروكلي المشوي لوجبة متكاملة\".","4","1 سمكة سلمون مرقط",
["2 ملعقة كبيرة نعناع طازج (مفروم ناعمًا)","2 ملعقة كبيرة إكليل الجبل طازج (مفروم ناعمًا)","2 ليمونة متوسطة (مقسّمة للاستخدام)","4 سمكات سلمون مرقط كاملة (نحو 7 أونصات لكل منها، منظّفة ومنزوعة الأحشاء والرأس (يمكن للبائع القيام بذلك نيابةً عنك))","1 ملعقة كبيرة زيت زيتون بكر ممتاز","½ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود"],
["حضّر مسبقًا أو كلّف غيرك: اُبشر قشر الليمون واعصر عصيره.","سخّن الشواية على حرارة متوسطة وادهن الشبك بالزيت لمنع التصاق السمك. (أو يمكنك خبز السمك على 400° فهرنهايت (205° مئوية) لمدة 25 دقيقة تقريبًا). في وعاء صغير، اخلط الأعشاب المفرومة وقشر 1½ ليمونة المبشور وعصير 1 ليمونة. قطّع الليمونة الأخرى إلى شرائح رقيقة.","ضع السمك على لوح التقطيع والجلد إلى الأعلى، وافرك الجلد بزيت الزيتون ليتغطى. اقلب السمك وافرك خليط الليمون والأعشاب على لحم السمك، وتبّله بالملح والفلفل، وضع شرائح الليمون فوق نصف كل سمكة. أغلق السمك على الأعشاب وشرائح الليمون، وانقله إلى الشواية.","اشوِ السمك والغطاء مغلق دون قلبه لمدة 8 دقائق أو حتى يصبح اللحم معتمًا ويتفتت بسهولة. استخدم مقلبًا عريضًا لنقل السمك بحذر إلى طبق التقديم. زيّن الطبق ببضع أوراق نعناع طازجة وأغصان إكليل الجبل إن رغبت.","طريقة الطهي في الطنجرة البطيئة: ضع كل قطعة سمك على قطعة منفصلة من ورق الألمنيوم، واحشُ كلًا منها بالتوابل والليمون. أغلق السمك على الأعشاب وشرائح الليمون، واطوِ ورق الألمنيوم على شكل علبة تحيط بالسمك تمامًا. ضع العلب في الطنجرة البطيئة واطهُها على درجة حرارة منخفضة لمدة 8–10 ساعات أو على درجة حرارة عالية لمدة 4–5 ساعات. (قد تختلف أوقات الطهي في الطنجرة البطيئة؛ تعرّف على طنجرتك البطيئة وعدّل أوقات الطهي عند الحاجة).","معزّز النكهة: تبّل السمك على المائدة بالفلفل الأسود المطحون طازجًا أو بتوابل الليمون والفلفل."])}))
R.append((6824681,{
"es":L("Aderezo de yogur y mostaza","Cremoso y con un toque cítrico, este aderezo fácil para ensaladas es un cambio agradable que realzará las ensaladas verdes y que también puede usarse como marinada para cerdo o pollo.","5","1 cucharada",
["1/4 cucharadita de sal kosher","1/4 cucharadita de pimienta negra","1 cucharadita de jugo de limón verde","2 cucharaditas de mostaza Dijon","1 cucharada de aceite de oliva","2 cucharadas de perejil fresco (picado finamente)","3 cucharadas de yogur griego natural sin grasa (sin grasa)"],
["Bata todos los ingredientes en un tazón pequeño. Tape y refrigere hasta por 3 días."]),
"ar":L("صلصة الزبادي والخردل","هذه الصلصة السهلة للسلطة كريمية ومنعشة، وهي تغيير لطيف يزيّن السلطات الخضراء ويمكن استخدامها أيضًا كتتبيلة للحم الخنزير أو الدجاج.","5","1 ملعقة كبيرة",
["¼ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود","1 ملعقة صغيرة عصير ليمون أخضر","2 ملعقة صغيرة خردل ديجون","1 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة بقدونس طازج (مفروم ناعمًا)","3 ملعقة كبيرة زبادي يوناني سادة خالٍ من الدسم (خالٍ من الدسم)"],
["اخفق جميع المكونات معًا في وعاء صغير. غطِّه وضعه في الثلاجة لمدة تصل إلى 3 أيام."])}))
